"use strict";(globalThis.webpackChunkjk_archive||=[]).push([[6185],{9233(e){e.exports=JSON.parse('{"tag":{"label":"gemini","permalink":"/docs/tags/gemini","allTagsPath":"/docs/tags","count":3,"items":[{"id":"ai/opendots-telegram-bot","title":"[AI/Agent] \uc624\ud508\uc18c\uc2a4 OpenDots \uc644\ubcbd \ucee4\uc2a4\ud140: Windows \ud658\uacbd \uad6c\ucd95\ubd80\ud130 Google Gemini \ubb34\ub8cc \uc5f0\ub3d9 \ubc0f \ud154\ub808\uadf8\ub7a8 \ubd07 \uac1c\ubc1c\uae30","description":"\ubcf8 \ud3ec\uc2a4\ud305\uc740 \uc624\ud508\uc18c\uc2a4 \uba40\ud2f0 \uc5d0\uc774\uc804\ud2b8 \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4\uc778 OpenDots\ub97c \ub85c\uceec Windows \ud658\uacbd\uc5d0 \uc124\uce58\ud558\uace0, \uc720\ub8cc \ud074\ub77c\uc6b0\ub4dc \uc885\uc18d\uc131\uc744 \uc81c\uac70\ud55c \ub4a4 Google Gemini \ubb34\ub8cc API \ubc0f Telegram Bot\uc744 \uc9c1\uc811 \uc5f0\ub3d9\ud558\uba74\uc11c \uacaa\uc740 \uc218\ub9ce\uc740 \ud2b8\ub7ec\ube14\uc288\ud305\uacfc \ud574\uacb0 \uacfc\uc815\uc744 \uc815\ub9ac\ud55c \uac1c\ubc1c\uae30\uc785\ub2c8\ub2e4.","permalink":"/docs/ai/opendots-windows-gemini-telegram-bot"},{"id":"dev/spring-ffmpeg-thumbnail","title":"[Spring Boot & AI] \ub300\uc6a9\ub7c9 \uc601\uc0c1 \uc378\ub124\uc77c \uc790\ub3d9\ud654: FFmpeg \uc624\ub514\uc624 \ucd94\ucd9c\ubd80\ud130 Render \ubc30\ud3ec\uae4c\uc9c0","description":"AI \uae30\ubc18\uc758 \ub3d9\uc601\uc0c1 \uc378\ub124\uc77c \ubc0f \ud558\uc774\ub77c\uc774\ud2b8 \uc1fc\uce20(15~30\ucd08) \uc790\ub3d9 \uc0dd\uc131 \uc2a4\ud29c\ub514\uc624\ub97c \uad6c\ucd95\ud558\uba74\uc11c \uc9c1\uba74\ud588\ub358 \ub300\uc6a9\ub7c9 \ubbf8\ub514\uc5b4 \ucc98\ub9ac \ubb38\uc81c\uc640, \uc774\ub97c FFmpeg \uc624\ub514\uc624 \ucd94\ucd9c \ud30c\uc774\ud504\ub77c\uc778 \ubc0f Gemini \uba40\ud2f0\ubaa8\ub2ec \uc624\ub514\uc624 \ubd84\uc11d\uc73c\ub85c \ud574\uacb0\ud55c \uacfc\uc815\uc744 \uacf5\uc720\ud569\ub2c8\ub2e4. \ub354\ubd88\uc5b4 \uc774\ub807\uac8c \ub9cc\ub4e0 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 FFmpeg \ud658\uacbd\uacfc \ud568\uaed8 Render(\ubb34\ub8cc \ud074\ub77c\uc6b0\ub4dc)\uc5d0 Docker\ub85c \ubb34\uc911\ub2e8 \ubc30\ud3ec\ud558\ub294 \ud301\uc744 \ub2e4\ub8f9\ub2c8\ub2e4.","permalink":"/docs/dev/spring-boot-ffmpeg-thumbnail-render"},{"id":"dev/saga-ai-studio-retrospective","title":"[\ud504\ub85c\uc81d\ud2b8 \ud68c\uace0] SAGA AI Studio \uac1c\ubc1c \ud604\ud669 \ubc0f \ud5a5\ud6c4 \ub85c\ub4dc\ub9f5","description":"\uac1c\uc778 \ud504\ub85c\uc81d\ud2b8\ub85c \uc2dc\uc791\ud55c \'SAGA AI Thumbnail Studio\'\uc758 1\ucc28 MVP(\ucd5c\uc18c \uae30\ub2a5 \uc81c\ud488) \ubc84\uc804\uc744 \ubc30\ud3ec\ud558\uba70, \uc9c0\uae08\uae4c\uc9c0 \uad6c\ud604\ud55c \ud575\uc2ec \uae30\uc220\ub4e4\uc744 \ub418\ub3cc\uc544\ubcf4\uace0 \uc55e\uc73c\ub85c\uc758 \uace0\ub3c4\ud654 \ubc29\ud5a5(To-Do List)\uc744 \uc815\ub9ac\ud558\ub294 \ud68c\uace0\ub85d\uc785\ub2c8\ub2e4.","permalink":"/docs/dev/saga-ai-studio-retrospective"}],"unlisted":false}}')}}]);